// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testRegression_property() public {
        address owner = address(this);
        address target = address(0x1234);
        vm.deal(owner, 2 ether);
        vm.startPrank(owner);
        (bool ok, ) = address(c).call{value: 1 ether}("");
        assertTrue(ok);
        bytes memory data = "";
        c.Command{value: 1 ether}(target, data);
        c.multiplicate{value: 0 ether}(address(0x5678));
        vm.stopPrank();
        uint256 targetBalance = target.balance;
        assertTrue(targetBalance == 1 ether);
    }
}
